    const models=campaignModels(campaignId);
    for(const [i,m]of models.entries()){
      const end=Math.max(2,m.dates.length+1),rows=[row(2,[cell(2,0,'Campaign Calendar',1)],28),row(3,[cell(3,0,workspace.title)],24),row(4,[cell(4,0,m.campaign.title)],28),row(5,[cell(5,0,dirty?'Draft plan · includes unsaved changes':'Saved draft plan'),cell(5,1,'Content Focus Legend',6),cell(5,2,'Awareness',3),cell(5,3,'Acquisition',4),cell(5,4,'Retention',5)],24)];
      const merges=['A2:'+col(end)+'2','A3:'+col(end)+'3','A4:'+col(end)+'4'];
      const weekCells=[cell(7,0,'Channel',2),cell(7,1,'Audience',2)];
      for(let d=0;d<m.dates.length;d+=7){weekCells.push(cell(7,d+2,'Week '+(Math.floor(d/7)+1),2));if(Math.min(d+6,m.dates.length-1)>d)merges.push(col(d+2)+'7:'+col(Math.min(d+6,m.dates.length-1)+2)+'7');}
      rows.push(row(7,weekCells,24),row(8,[cell(8,0,'',2),cell(8,1,'',2),...m.dates.map((d,j)=>cell(8,j+2,serial(d),9))],36));
      m.rows.forEach((r,n)=>{const rr=9+n;let height=80;const cells=m.dates.map((d,j)=>{const events=m.at(r,d);const text=events.map(e=>e.title+'\n'+m.topic(e)+'\n'+e.role+' · '+(e.status||'idea').replace(/_/g,' ')).join('\n\n');const tone=events.length===1?({Awareness:3,Acquisition:4,Retention:5}[events[0].role]||0):0;height=Math.min(409,Math.max(height,Math.ceil(text.length/26)*13+12));return cell(rr,j+2,text,events.length?tone:(new Date(d+'T00:00:00Z').getUTCDay()%6===0?7:0));});rows.push(row(rr,[cell(rr,0,r.channel,6),cell(rr,1,r.audience,6),...cells],height));});
      let last=9+m.rows.length;if(m.unplaced.length){rows.push(row(last,[cell(last,0,'Items outside campaign dates or undated are included on Content Details.',8)],30));merges.push('A'+last+':'+col(end)+last);}
      sheet(i?'Calendar '+(i+1):'Campaign Calendar',rows,[16,32,...m.dates.map(()=>28)],end,last,{x:2,y:8},merges,'$1:$8');
    }
    if(!models.length)throw new Error('Add a campaign before exporting the calendar.');
    const planRows=[row(2,[cell(2,0,'Campaign Plan',1)],28),row(3,[cell(3,0,workspace.title)],24)];let pr=5;
    for(const m of models){for(const [k,v]of [['Campaign',m.campaign.title],['Start date',Number.isFinite(dayMillis(m.campaign.start))?serial(m.campaign.start):''],['Days',Number(m.campaign.days)],['Channels',(m.campaign.channels||[]).join(', ')],['Objective',m.campaign.objective],['Cadence',m.campaign.cadence],['Refinement',m.campaign.refinement]]){planRows.push(row(pr,[cell(pr,0,k,6),cell(pr,1,v,k==='Start date'?10:0)],Math.min(409,Math.max(24,Math.ceil(String(v||'').length/130)*13+12))));pr++;}pr++;}
