    const headers=['Date','Campaign','Channel','Title','Audience','Topic','Brand Axis purpose','Status','Actual publication date'];
    const details=[row(1,headers.map((h,i)=>cell(1,i,h,2)),32)];calendarEvents(campaignId).forEach((e,i)=>{const c=draft.cells.find(v=>v.id===e.cell_id);const values=[Number.isFinite(dayMillis(e.date))?serial(e.date):'',draft.campaigns.find(v=>v.id===e.campaign_id)?.title||'Unassigned',e.channel,e.title,draft.audiences.find(v=>v.id===c?.audience_id)?.name||'',draft.buckets.find(v=>v.id===c?.bucket_id)?.name||'',e.role,(e.status||'idea').replace(/_/g,' '),Number.isFinite(dayMillis(e.actual_date))?serial(e.actual_date):''];details.push(row(i+2,values.map((v,j)=>cell(i+2,j,v,j===0||j===8?10:0)),42));});
